  for c in range(1,w-1):
   if not all(grid[y][x]!=0 for y in range(r-1,r+2) for x in range(c-1,c+2)): continue
   d=[]
   for sr,sc,col in seeds:
    if metric=='manhattan': dist=abs(sr-r)+abs(sc-c)
    elif metric=='euclidean': dist=(sr-r)**2+(sc-c)**2
    else: dist=max(abs(sr-r),abs(sc-c))
    d.append((dist,col))
